 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        q = (y + dy, x + dx)
                        if (0 <= q[0] < h and 0 <= q[1] < w
                                and grid[q[0]][q[1]] != 0 and q not in seen):
                            seen.add(q)
                            stack.append(q)
            comps.append(cells)

    # The selected motif is the lowest one; in a vertical tie, take the rightmost.
    cells = max(comps, key=lambda co: (max(y for y, x in co), max(x for y, x in co)))
    r0 = min(y for y, x in cells)
    r1 = max(y for y, x in cells)
    c0 = min(x for y, x in cells)
    c1 = max(x for y, x in cells)

    # Include colored pixels touching the motif's bounding frame (some motifs have
    # a detached dot along the edge of the same rectangular pattern).
    changed = True
    while changed:
        changed = False
        for y in range(max(0, r0 - 1), min(h, r1 + 2)):
            for x in range(max(0, c0 - 1), min(w, c1 + 2)):
                if grid[y][x] == 0 or (r0 <= y <= r1 and c0 <= x <= c1):
